import heapq

def min_coupons(N, trips):
    trips.sort(key=lambda x: x[1])
    pq = []
    current_time = 0
    total_coupons = 0

    for zone, time in trips:
        while pq and pq[0][0] < time:
            _, cost, start_zone, end_zone = heapq.heappop(pq)
            if start_zone <= zone <= end_zone:
                break

        if pq:
            _, cost, start_zone, end_zone = pq[0]
            if start_zone <= zone <= end_zone:
                continue

        if pq:
            _, prev_cost, prev_start_zone, prev_end_zone = pq[-1]
            if prev_start_zone <= zone <= prev_end_zone:
                continue

        if pq:
            _, prev_cost, prev_start_zone, prev_end_zone = pq[-1]
            if prev_end_zone >= zone:
                continue

        if pq:
            _, prev_cost, prev_start_zone, prev_end_zone = pq[-1]
            if prev_end_zone < zone:
                cost = 2 + abs(prev_end_zone - zone)
                heapq.heappush(pq, (time + 10000, cost, prev_end_zone, zone))
                total_coupons += cost
                continue

        cost = 2 + abs(zone)
        heapq.heappush(pq, (time + 10000, cost, 0, zone))
        total_coupons += cost

    return total_coupons

